async createErasureRequest(
  client: pg.PoolClient,
  merchantId: string,
  customerId: string,
  idempotencyKey: string,
): Promise<{ id: string; customer_id: string; status: string; attempts: number; created_at: Date; updated_at: Date; completed_at: Date | null; last_error: string | null } | undefined> {
  const result = await client.query(
    `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key)
     SELECT $1,id,$3 FROM customers.customers WHERE merchant_id=$1 AND id=$2 AND status='active'
     ON CONFLICT(merchant_id,customer_id) DO UPDATE SET updated_at=customers.erasure_requests.updated_at
     RETURNING id,customer_id,status,attempts,created_at,updated_at,completed_at,last_error`,
    [merchantId, customerId, idempotencyKey],
  );
  if (!result.rows[0]) return undefined;
  await client.query(`UPDATE customers.customers SET status='erasure_pending',updated_at=now() WHERE merchant_id=$1 AND id=$2`, [merchantId, customerId]);
  await client.query(
    `INSERT INTO operations.jobs(queue,job_type,merchant_id,payload,erasure_request_id)
     VALUES('privacy','erase_customer',$1,$2,$3) ON CONFLICT(erasure_request_id) DO NOTHING`,
    [merchantId, { merchantId, customerId, requestId: result.rows[0].id }, result.rows[0].id],
  );
  return result.rows[0];
}

async findErasureRequest(merchantId: string, requestId: string): Promise<Record<string, unknown> | undefined> {
  const result = await pool.query(
    `SELECT id,customer_id,status,attempts,created_at,updated_at,completed_at,last_error
     FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`, [merchantId, requestId],
  );
  return result.rows[0] as Record<string, unknown> | undefined;
}

async erasureObjectKeys(client: pg.PoolClient, merchantId: string, customerId: string): Promise<string[]> {
  const result = await client.query<{ object_key: string }>(
    `SELECT object_key FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId],
  );
  return result.rows.map((row) => row.object_key);
}

async eraseCustomer(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
  await client.query(`DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`DELETE FROM customers.support_participants WHERE customer_id=$1`, [customerId]);
  await client.query(`DELETE FROM customers.support_messages WHERE merchant_id=$1 AND author_id=$2`, [merchantId, customerId]);
  await client.query(`DELETE FROM customers.customer_imports WHERE merchant_id=$1 AND id IN (SELECT id FROM customers.customer_imports WHERE merchant_id=$1) AND object_key IN (SELECT object_key FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2)`, [merchantId, customerId]);
  await client.query(`DELETE FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`UPDATE payments.payment_intents SET customer_snapshot='{}'::jsonb,description=NULL,updated_at=now() WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`UPDATE payments.refunds SET customer_email=NULL WHERE merchant_id=$1 AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`, [merchantId, customerId]);
  await client.query(`UPDATE payments.invoices SET billing_snapshot='{}'::jsonb,object_key=NULL WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`DELETE FROM provider_sandbox.customers WHERE merchant_id=$1 AND payflow_customer_id=$2`, [merchantId, customerId]);
  await client.query(`UPDATE operations.analytics_events SET customer_id=NULL,anonymous_id=NULL,email=NULL,properties='{}'::jsonb WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`UPDATE operations.notification_preferences SET destination='deleted' WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`UPDATE operations.notifications SET customer_id=NULL,destination='deleted',payload='{}'::jsonb,status='cancelled',updated_at=now() WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`UPDATE operations.email_deliveries SET customer_id=NULL,destination='deleted',status='cancelled',cancelled_at=now() WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  await client.query(`UPDATE operations.jobs SET payload=payload-'customerSnapshot'-'customerEmail',status=CASE WHEN status IN ('pending','retry','processing') THEN 'completed' ELSE status END WHERE merchant_id=$1 AND payload->>'customerId'=$2`, [merchantId, customerId]);
  await client.query(`UPDATE operations.outbox_events SET payload=payload-'email'-'customerEmail'-'customerSnapshot' WHERE merchant_id=$1 AND payload->>'customerId'=$2`, [merchantId, customerId]);
  await client.query(`DELETE FROM customers.customers WHERE merchant_id=$1 AND id=$2`, [merchantId, customerId]);
}

