      await client.query(
        `UPDATE customers.erasure_requests SET status='completed',completed_at=now(),updated_at=now(),last_error=NULL WHERE id=$1`,
        [job.payload.requestId],
      );
      await completeJob(client, job);
    });
  } catch {
    await transaction(async (client) => {
      await client.query(
